250	                    .setName(topic)
251	                    .setNumPartitions(transactionLogConfig.transactionTopicPartitions())
252	                    .setReplicationFactor(transactionLogConfig.transactionTopicReplicationFactor())
253	                    .setConfigs(convertToTopicConfigCollections(transactionTopicConfigsSupplier.get()));
254	            }
255	            case Topic.SHARE_GROUP_STATE_TOPIC_NAME -> {
256	                var shareCoordinatorConfig = new ShareCoordinatorConfig(config);
257	                yield new CreatableTopic()
258	                    .setName(topic)
259	                    .setNumPartitions(shareCoordinatorConfig.shareCoordinatorStateTopicNumPartitions())
260	                    .setReplicationFactor(shareCoordinatorConfig.shareCoordinatorStateTopicReplicationFactor())
261	                    .setConfigs(convertToTopicConfigCollections(shareCoordinatorConfigsSupplier.get()));
262	            }
263	            default -> {
264	                int numPartitions = config.originals().containsKey(ServerLogConfigs.NUM_PARTITIONS_CONFIG)
265	                        ? config.numPartitions()
266	                        : CreateTopicsRequest.NO_NUM_PARTITIONS;
267	                short replicationFactor = config.originals().containsKey(ReplicationConfigs.DEFAULT_REPLICATION_FACTOR_CONFIG)
268	                        ? (short) config.defaultReplicationFactor()
269	                        : CreateTopicsRequest.NO_REPLICATION_FACTOR;
270	                yield new CreatableTopic()
271	                        .setName(topic)
272	                        .setNumPartitions(numPartitions)
273	                        .setReplicationFactor(replicationFactor);
274	            }
275	        };
